config.py:
"""Small, strict TOML configuration with no optional framework dependency."""

import math
import tomllib
from dataclasses import asdict, dataclass, fields
from pathlib import Path


@dataclass(frozen=True)
class ExperimentConfig:
    dataset: str = "data/processed/dev_set.json"
    limit: int = 3
    k: int = 5
    short_pool_policy: str = "use_all"
    alpha: float = 1.0
    beta: float = 0.2
    seed: int = 42
    device: str = "cpu"
    threads: int = 4
    local_files_only: bool = True
    embedding_model: str = "sentence-transformers/all-MiniLM-L6-v2"
    embedding_revision: str = "1110a243fdf4706b3f48f1d95db1a4f5529b4d41"
    generator_model: str = "Qwen/Qwen2.5-1.5B-Instruct"
    generator_revision: str = "989aa7980e4cf806f80c7fef2b1adb7bc71aa306"
    embedding_truncation: str = "error"
    max_input_tokens: int = 4096
    max_new_tokens: int = 32
    solver_time_limit: float = 10.0
    generator_dtype: str = "float32"

    def __post_init__(self) -> None:
        for name in ("limit", "k", "threads", "max_input_tokens", "max_new_tokens"):
            if type(getattr(self, name)) is not int or getattr(self, name) <= 0:
                raise ValueError(f"{name} must be a positive integer")
        if type(self.seed) is not int or not 0 <= self.seed < 2**32:
            raise ValueError("seed must be an integer in [0, 2**32)")
        if type(self.local_files_only) is not bool:
            raise ValueError("local_files_only must be boolean")
        for name in ("alpha", "beta", "solver_time_limit"):
            value = getattr(self, name)
            if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
                raise ValueError(f"{name} must be finite and nonnegative")
        if self.solver_time_limit == 0:
            raise ValueError("solver_time_limit must be positive")
        if self.device not in {"cpu", "cuda", "auto"}:
            raise ValueError("device must be cpu, cuda or auto")
        if self.generator_dtype not in {"float32", "float16", "bfloat16"}:
            raise ValueError("generator_dtype must be float32, float16 or bfloat16")
        if self.short_pool_policy not in {"error", "use_all"}:
            raise ValueError("short_pool_policy must be error or use_all")
        if self.embedding_truncation not in {"error", "report"}:
            raise ValueError("embedding_truncation must be error or report")
        for name in ("dataset", "embedding_model", "generator_model"):
            if (
                not isinstance(getattr(self, name), str)
                or not getattr(self, name).strip()
            ):
                raise ValueError(f"{name} must be a nonempty string")
        for name in ("embedding_revision", "generator_revision"):
            value = getattr(self, name)
            if (
                not isinstance(value, str)
                or len(value) != 40
                or any(ch not in "0123456789abcdef" for ch in value)
            ):
                raise ValueError(f"{name} must be an immutable 40-character commit")

    def as_dict(self) -> dict:
        return asdict(self)


def load_config(path: Path) -> ExperimentConfig:
    raw = tomllib.loads(path.read_text(encoding="utf-8"))
    unknown = set(raw) - {field.name for field in fields(ExperimentConfig)}
    if unknown:
        raise ValueError(f"Unknown configuration keys: {sorted(unknown)}")
    return ExperimentConfig(**raw)

corpus.py:
"""Bounded corpus retrieval built from inference documents, without annotations."""

import hashlib
import json
import re
from dataclasses import asdict
from pathlib import Path
from time import perf_counter

import numpy as np

from qrag.data import Document
from qrag.experiments.artifacts import file_hash, value_hash, write_json
from qrag.retrieval import ExactIndex, chunk_document, reciprocal_rank_fusion


def corpus_id(title, text):
    return "corpus:" + hashlib.sha256((title + "\n" + text).encode()).hexdigest()[:24]


def deduplicate(documents):
    unique = {}
    for doc in documents:
        key = corpus_id(doc.title, doc.text)
        unique.setdefault(key, Document(key, doc.title, doc.text, doc.sentences, key))
    return tuple(unique[key] for key in sorted(unique))


class CorpusRetriever:
    def __init__(self, directory: Path, encoder):
        from rank_bm25 import BM25Okapi

        manifest = json.loads((directory / "corpus.json").read_text())
        if (
            manifest["representation"] != encoder.identity
            or file_hash(directory / "documents.json") != manifest["documents_sha256"]
        ):
            raise ValueError("Corpus metadata/representation mismatch")
        self.documents = tuple(
            Document(**{**d, "sentences": tuple(d["sentences"])})
            for d in json.loads((directory / "documents.json").read_text())
        )
        self.index = ExactIndex(directory / "index", encoder.identity)
        self.encoder = encoder
        self.positions = {d.id: i for i, d in enumerate(self.documents)}
        self.bm25 = BM25Okapi(
            [
                re.findall(r"\w+", (d.title + " " + d.text).casefold())
                for d in self.documents
            ]
        )
        self.manifest = manifest

    @classmethod
    def build(cls, directory, documents, encoder):
        docs = deduplicate(documents)
        content_identity = value_hash([(d.id, d.title, d.text) for d in docs])
        if directory.exists():
            manifest = json.loads((directory / "corpus.json").read_text())
            if manifest["content_identity"] != content_identity:
                raise ValueError("Existing corpus has different source content")
            return cls(directory, encoder)
        directory.mkdir(parents=True)
        chunks = [
            c
            for d in docs
            for c in chunk_document(d, encoder.tokenizer, encoder.max_tokens)
        ]
        vectors = encoder.encode([c.embedding_text for c in chunks])
        ExactIndex.build(directory / "index", chunks, vectors, encoder.identity)
        write_json(directory / "documents.json", [asdict(d) for d in docs])
        write_json(
            directory / "corpus.json",
            {
                "content_identity": content_identity,
                "documents": len(docs),
                "chunks": len(chunks),
                "representation": encoder.identity,
                "documents_sha256": file_hash(directory / "documents.json"),
                "scope": "bounded union of benchmark input passages; not full Wikipedia",
            },
        )
        return cls(directory, encoder)

    def retrieve(self, question, count=100, mode="hybrid", unique_titles=False):
        started = perf_counter()
        if mode not in {"dense", "bm25", "hybrid"} or count < 1:
            raise ValueError("Invalid corpus retrieval settings")
        vector = self.encoder.encode([question], kind="query")[0]
        hits = self.index.search(vector, len(self.index.rows))
        dense = np.full(len(self.documents), -1.0, dtype=float)
        for chunk, score in hits:
            position = self.positions[chunk["source_id"]]
            dense[position] = max(dense[position], score)
        lexical = np.asarray(
            self.bm25.get_scores(re.findall(r"\w+", question.casefold()))
        )
        scores = {
            "dense": dense,
            "bm25": lexical,
            "hybrid": reciprocal_rank_fusion(dense, lexical),
        }[mode]
        selected = []
        seen = set()
        for position in np.argsort(-scores, kind="stable"):
            doc = self.documents[int(position)]
            if unique_titles and doc.title in seen:
                continue
            seen.add(doc.title)
            selected.append(doc)
            if len(selected) == count:
                break
        return tuple(selected), {
            "seconds": perf_counter() - started,
            "mode": mode,
            "requested": count,
            "returned": len(selected),
            "corpus_documents": len(self.documents),
            "candidate_ids": [d.id for d in selected],
        }

data.py:
"""Adapt the existing processed HotpotQA data without passing labels to selectors."""

import json
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class Document:
    id: str
    title: str
    text: str
    sentences: tuple[str, ...] = ()
    source_id: str = ""


@dataclass(frozen=True)
class QueryInput:
    id: str
    question: str
    documents: tuple[Document, ...]


@dataclass(frozen=True)
class EvaluationLabels:
    answer: str
    supporting_titles: frozenset[str]
    supporting_sentences: frozenset[tuple[str, int]] = frozenset()
    aliases: tuple[str, ...] = ()
    dataset: str = "hotpotqa"
    supporting_ids: frozenset[str] = frozenset()


def _string(value: object, name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must be a nonempty string")
    return value


def adapt_example(raw: dict) -> tuple[QueryInput, EvaluationLabels]:
    """The first object is safe for inference; only the evaluator gets the second."""
    query_id = _string(raw["id"], "id")
    question = _string(raw["question"], "question")
    raw_documents = raw["documents"]
    if not isinstance(raw_documents, list) or not raw_documents:
        raise ValueError(f"{query_id}: documents must be a nonempty list")
    documents = tuple(
        Document(
            id=_string(doc.get("id", f"{query_id}:d{i}"), "document id"),
            title=_string(doc["title"], "title"),
            text=_string(doc["text"], "text"),
            sentences=tuple(doc.get("sentences", ())),
            source_id=str(doc.get("source_id", f"{query_id}:d{i}")),
        )
        for i, doc in enumerate(raw_documents)
    )
    if len({doc.id for doc in documents}) != len(documents):
        raise ValueError(f"{query_id}: duplicate document IDs")
    if raw.get("dataset", "hotpotqa") != "musique" and len(
        {doc.title for doc in documents}
    ) != len(documents):
        raise ValueError(f"{query_id}: duplicate document titles are ambiguous")
    # Gold annotations are read only into the evaluation object.
    support = raw.get("supporting_facts", {}).get("titles")
    if support is None:
        support = [doc["title"] for doc in raw_documents if doc.get("is_relevant")]
    if not isinstance(support, list) or any(not isinstance(t, str) for t in support):
        raise ValueError(f"{query_id}: invalid supporting titles")
    for doc in documents:
        if any(not isinstance(s, str) for s in doc.sentences):
            raise ValueError(f"{query_id}: sentences must be strings")
        if doc.sentences and " ".join(doc.sentences) != doc.text:
            raise ValueError(f"{query_id}: sentence join differs from source text")
    details = raw.get("supporting_facts", {}).get("details", [])
    sentence_labels = frozenset((d["title"], int(d["sent_id"])) for d in details)
    by_title = {doc.title: doc for doc in documents}
    external = raw.get("candidate_source") == "retrieved"
    for title, index in sentence_labels:
        if not external and (
            title not in by_title or not 0 <= index < len(by_title[title].sentences)
        ):
            raise ValueError(f"{query_id}: invalid supporting sentence mapping")
    if not external and not set(support) <= set(by_title):
        raise ValueError(f"{query_id}: supporting title missing from candidates")
    aliases = raw.get("answer_aliases", [])
    if not isinstance(aliases, list) or any(not isinstance(a, str) for a in aliases):
        raise ValueError(f"{query_id}: invalid answer aliases")
    supporting_ids = frozenset(raw.get("supporting_ids", []))
    if not external and not supporting_ids <= {doc.id for doc in documents}:
        raise ValueError(f"{query_id}: supporting ID missing from candidates")
    labels = EvaluationLabels(
        _string(raw["answer"], "answer"),
        frozenset(support),
        sentence_labels,
        tuple(aliases),
        raw.get("dataset", "hotpotqa"),
        supporting_ids,
    )
    return QueryInput(query_id, question, documents), labels


def load_examples(path: Path) -> list[tuple[QueryInput, EvaluationLabels]]:
    raw = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(raw, list) or not raw:
        raise ValueError("Dataset must be a nonempty JSON list")
    examples = [adapt_example(example) for example in raw]
    if len({query.id for query, _ in examples}) != len(examples):
        raise ValueError("Dataset contains duplicate question IDs")
    return examples

datasets.py:
"""Primary-dataset adapters and deterministic, label-independent split selection."""

import re
from collections import Counter

from qrag.data import adapt_example
from qrag.metrics import answer_metrics, normalize_answer


def hotpot_record(row: dict) -> dict:
    titles = row["context"]["title"]
    sentences = row["context"]["sentences"]
    support = row["supporting_facts"]
    return {
        "id": row["id"],
        "question": row["question"],
        "answer": row["answer"],
        "dataset": "hotpotqa",
        "type": row["type"],
        "level": row["level"],
        "documents": [
            {"title": title, "sentences": sents, "text": " ".join(sents)}
            for title, sents in zip(titles, sentences, strict=True)
        ],
        "supporting_facts": {
            "titles": sorted(set(support["title"])),
            "details": [
                {"title": t, "sent_id": s}
                for t, s in zip(support["title"], support["sent_id"], strict=True)
            ],
        },
    }


def musique_record(row: dict) -> dict:
    if not row.get("answerable", True):
        raise ValueError("Only MuSiQue-Ans answerable examples are supported")
    documents = [
        {"title": p["title"], "text": p["paragraph_text"], "source_id": str(p["idx"])}
        for p in row["paragraphs"]
    ]
    ids = [
        f"{row['id']}:d{i}"
        for i, p in enumerate(row["paragraphs"])
        if p["is_supporting"]
    ]
    return {
        "id": row["id"],
        "question": row["question"],
        "answer": row["answer"],
        "answer_aliases": row.get("answer_aliases", []),
        "dataset": "musique",
        "documents": documents,
        "supporting_ids": ids,
        "supporting_facts": {
            "titles": sorted(
                {p["title"] for p in row["paragraphs"] if p["is_supporting"]}
            )
        },
    }


def score_answer(prediction: str, labels) -> dict:
    if labels.dataset == "hotpotqa":
        return answer_metrics(prediction, labels.answer)
    # MuSiQue uses SQuAD-style alias maxima; no Hotpot yes/no exception.
    from collections import Counter

    def pair(reference):
        p, g = normalize_answer(prediction).split(), normalize_answer(reference).split()
        overlap = sum((Counter(p) & Counter(g)).values())
        f1 = float(p == g) if not p or not g else 2 * overlap / (len(p) + len(g))
        return float(p == g), f1

    scores = [pair(reference) for reference in (labels.answer, *labels.aliases)]
    return {
        "answer_em": max(s[0] for s in scores),
        "answer_f1": max(s[1] for s in scores),
    }


def score_evidence(selected, labels) -> dict:
    gold = labels.supporting_ids or labels.supporting_titles
    predicted = (
        {d.id for d in selected}
        if labels.supporting_ids
        else {d.title for d in selected}
    )
    overlap = len(predicted & gold)
    return {
        "document_recall": overlap / len(gold) if gold else None,
        "document_precision": overlap / len(predicted) if predicted else 0.0,
        "all_supporting_documents": float(gold <= predicted) if gold else None,
    }


def question_key(text: str) -> str:
    return " ".join(re.findall(r"\w+", text.casefold()))


def shingles(text: str) -> frozenset[str]:
    words = question_key(text).split()
    return frozenset(" ".join(words[i : i + 3]) for i in range(max(1, len(words) - 2)))


def duplicate_audit(
    development: list[dict], evaluation: list[dict], threshold=0.8
) -> dict:
    """Exact normalized questions plus token-trigram Jaccard; not a contamination proof."""
    seen = {}
    inverted = {}
    for row in development:
        terms = shingles(row["question"])
        seen[row["id"]] = terms
        for term in terms:
            inverted.setdefault(term, set()).add(row["id"])
    matches = []
    exact = {question_key(row["question"]) for row in development}
    for row in evaluation:
        terms = shingles(row["question"])
        candidates = set().union(*(inverted.get(t, set()) for t in terms))
        similarities = [
            (q, len(terms & seen[q]) / max(1, len(terms | seen[q]))) for q in candidates
        ]
        near = [(q, score) for q, score in similarities if score >= threshold]
        if near or question_key(row["question"]) in exact:
            matches.append(
                {
                    "id": row["id"],
                    "matches": sorted(near),
                    "exact": question_key(row["question"]) in exact,
                }
            )
    return {
        "threshold": threshold,
        "method": "normalized question exact + word trigram Jaccard",
        "matches": matches,
        "limitations": "Does not detect paraphrase or pretrained-model contamination.",
    }


def validate_records(records: list[dict]) -> dict:
    counts = Counter()
    ids = set()
    for row in records:
        query, labels = adapt_example(row)
        if query.id in ids:
            raise ValueError("duplicate query ID")
        ids.add(query.id)
        counts["questions"] += 1
        counts["documents"] += len(query.documents)
        counts["supporting_sentence_annotations"] += len(labels.supporting_sentences)
        counts["answer_aliases"] += len(labels.aliases)
    return dict(counts)

evaluation.py:
"""Question-level paired uncertainty, keeping solver repeats inside each question."""

import json
import re
from collections import defaultdict
from pathlib import Path

import numpy as np


def latest_records(path):
    records = {}
    for line in Path(path).read_text().splitlines():
        row = json.loads(line)
        records[(row["question_id"], row["method"])] = row
    return list(records.values())


def question_scores(records, metric="answer_f1", group_seeds=True):
    groups = defaultdict(lambda: defaultdict(list))
    for row in records:
        method = re.sub(r"_s\d+$", "", row["method"]) if group_seeds else row["method"]
        value = (
            row.get("metrics", {}).get(metric, 0.0)
            if row["status"] == "success"
            else 0.0
        )
        groups[method][row["question_id"]].append(value)
    return {
        method: {q: float(np.mean(values)) for q, values in questions.items()}
        for method, questions in groups.items()
    }


def paired_interval(first, second, resamples=10000, seed=20261110):
    if set(first) != set(second) or not first:
        raise ValueError("Paired comparison requires the same nonempty question set")
    ids = sorted(first)
    differences = np.array([first[q] - second[q] for q in ids])
    rng = np.random.default_rng(seed)
    means = []
    # Bounded memory even for large studies.
    for start in range(0, resamples, 500):
        count = min(500, resamples - start)
        means.extend(
            np.mean(
                differences[rng.integers(0, len(ids), size=(count, len(ids)))], axis=1
            ).tolist()
        )
    low, high = np.quantile(means, [0.025, 0.975])
    return {
        "questions": len(ids),
        "mean_difference": float(differences.mean()),
        "ci95": [float(low), float(high)],
        "resamples": resamples,
        "seed": seed,
        "method": "paired question bootstrap; solver repeats averaged within question",
    }


def analyze(records, reference=None):
    grouped = question_scores(records)
    grouped_em = question_scores(records, metric="answer_em")
    reference = reference or (
        "milp_full"
        if "milp_full" in grouped
        else "top_k"
        if "top_k" in grouped
        else next(iter(grouped))
    )
    table = {}
    for method, scores in sorted(grouped.items()):
        rows = [r for r in records if re.sub(r"_s\d+$", "", r["method"]) == method]
        good = [r for r in rows if r["status"] == "success"]
        summary = {
            "questions": len(scores),
            "attempted_method_records": len(rows),
            "failures": len(rows) - len(good),
            "answer_f1": float(np.mean(list(scores.values()))),
            "answer_em": float(np.mean(list(grouped_em[method].values()))),
        }
        for key in [
            "context_tokens",
            "input_tokens",
            "selection_seconds",
            "actual_generation_seconds",
            "full_energy",
        ]:
            values = [r[key] for r in good if key in r]
            summary[key + "_successful_only"] = (
                float(np.mean(values)) if values else None
            )
        for key in ["document_recall", "all_supporting_documents"]:
            values = [
                r["metrics"][key] for r in good if r["metrics"].get(key) is not None
            ]
            summary[key + "_successful_only"] = (
                float(np.mean(values)) if values else None
            )
        resources = [r["resources"] for r in good if r.get("resources")]
        for key in ["feasible_fraction"]:
            values = [r[key] for r in resources if key in r]
            summary[key + "_successful_only"] = (
                float(np.mean(values)) if values else None
            )
        for target in ["all_to_all", "line"]:
            values = [r[target]["two_qubit_gates"] for r in resources if target in r]
            summary[target + "_two_qubit_gates_successful_only"] = (
                float(np.mean(values)) if values else None
            )
        table[method] = summary
    comparisons = {
        method: paired_interval(scores, grouped[reference])
        for method, scores in grouped.items()
        if method != reference and set(scores) == set(grouped[reference])
    }
    principal = None
    if "xy_evidence_f0.5" in grouped and "xy_absolute_f0.5" in grouped:
        principal = paired_interval(
            grouped["xy_evidence_f0.5"], grouped["xy_absolute_f0.5"]
        )
    return {
        "reference": reference,
        "table": table,
        "paired_differences_to_reference": comparisons,
        "principal_evidence_minus_absolute_f1": principal,
        "interpretation": "Exploratory intervals unless a comparison is explicitly primary in the frozen protocol. No noninferiority or hardware-speedup claim.",
    }

experiments/artifacts.py:
"""Atomic artifacts and a strict resume identity, including uncommitted source."""

import hashlib
import importlib.metadata
import json
import os
import platform
import subprocess
import tempfile
from datetime import datetime, timezone
from pathlib import Path


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def file_hash(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def value_hash(value: object) -> str:
    return hashlib.sha256(
        json.dumps(
            value,
            sort_keys=True,
            allow_nan=False,
        ).encode()
    ).hexdigest()


def source_hash() -> str:
    root = Path(__file__).resolve().parents[1]
    return value_hash(
        {
            str(path.relative_to(root)): file_hash(path)
            for path in sorted(root.rglob("*.py"))
        }
    )


def environment() -> dict:
    versions = {}
    for name in (
        "numpy",
        "scipy",
        "torch",
        "transformers",
        "sentence-transformers",
        "huggingface-hub",
        "tokenizers",
        "safetensors",
    ):
        try:
            versions[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            versions[name] = None
    return {
        "python": platform.python_version(),
        "platform": platform.platform(),
        "packages": versions,
    }


def git_state() -> dict:
    def read(*args: str) -> str | None:
        try:
            return subprocess.check_output(
                ["git", *args],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        except (OSError, subprocess.CalledProcessError):
            return None

    return {
        "commit": read("rev-parse", "HEAD"),
        "status": read("status", "--short"),
        "tracked_diff_sha256": value_hash(read("diff", "HEAD")),
    }


def atomic_text(path: Path, contents: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            dir=path.parent,
            delete=False,
        ) as handle:
            temporary = Path(handle.name)
            handle.write(contents)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def write_json(path: Path, value: object) -> None:
    atomic_text(
        path, json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n"
    )


class RunStore:
    def __init__(self, directory: Path, identity: dict, resume: bool = False):
        self.directory = directory
        self.records: dict[tuple[str, str], dict] = {}
        manifest_path = directory / "manifest.json"
        identity_sha256 = value_hash(identity)
        if resume:
            self.manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            if self.manifest["identity_sha256"] != identity_sha256:
                raise ValueError(
                    "Resume identity mismatch: code, config, data or runtime changed"
                )
            path = directory / "predictions.jsonl"
            if path.exists():
                for line in path.read_text(encoding="utf-8").splitlines():
                    record = json.loads(line)
                    key = (record["question_id"], record["method"])
                    if key in self.records:
                        raise ValueError(f"Duplicate prediction record: {key}")
                    self.records[key] = record
        else:
            directory.mkdir(parents=True, exist_ok=False)
            self.manifest = {
                "manifest_version": 1,
                "created_at": utc_now(),
                "identity": identity,
                "identity_sha256": identity_sha256,
                "git": git_state(),
                "status": "created",
                "invocations": [],
            }
            write_json(manifest_path, self.manifest)

    def save_manifest(self) -> None:
        write_json(self.directory / "manifest.json", self.manifest)

    def save_record(self, record: dict) -> None:
        key = (record["question_id"], record["method"])
        if key in self.records:
            raise ValueError(f"Record already exists: {key}")
        self.records[key] = record
        atomic_text(
            self.directory / "predictions.jsonl",
            "".join(
                json.dumps(item, sort_keys=True, allow_nan=False) + "\n"
                for item in self.records.values()
            ),
        )

