"""Run fixed-count top-k and MILP on shared candidates, then score actual answers."""

import argparse
import json
import random
import traceback
from dataclasses import asdict
from pathlib import Path
from time import perf_counter

import numpy as np

from qrag.config import ExperimentConfig, load_config
from qrag.data import load_examples
from qrag.experiments.artifacts import (
    RunStore,
    environment,
    file_hash,
    source_hash,
    utc_now,
    write_json,
)
from qrag.metrics import answer_metrics, evidence_metrics
from qrag.optimization import build_problem, select_milp, select_top_k

METHODS = ("top_k", "milp")


def summarize(records: list[dict]) -> dict:
    summary = {"scope": "development_smoke_run", "methods": {}}
    for method in METHODS:
        rows = [record for record in records if record["method"] == method]
        good = [record for record in rows if record["status"] == "success"]
        count = len(rows)
        means = {}
        for metric in ("answer_em", "answer_f1"):
            means[f"{metric}_all_questions"] = (
                sum(record.get("metrics", {}).get(metric, 0.0) for record in rows)
                / count
                if count
                else None
            )
        for metric in ("document_recall", "all_supporting_documents"):
            observed = [
                record["metrics"][metric]
                for record in good
                if record["metrics"][metric] is not None
            ]
            means[f"{metric}_successful_only"] = (
                float(np.mean(observed)) if observed else None
            )
        for key in (
            "selected_count",
            "context_tokens",
            "input_tokens",
            "generation_seconds",
        ):
            means[f"mean_{key}_successful_only"] = (
                float(np.mean([record[key] for record in good])) if good else None
            )
        summary["methods"][method] = {
            "questions": count,
            "successful": len(good),
            "failed": count - len(good),
            **means,
        }
    return summary


def run_experiment(
    config: ExperimentConfig,
    output: Path,
    *,
    resume: bool = False,
    backend=None,
) -> dict:
    """Backend injection is for offline tests; the CLI always uses real local models."""
    random.seed(config.seed)
    np.random.seed(config.seed)
    dataset_path = Path(config.dataset).resolve()
    examples = load_examples(dataset_path)[: config.limit]
    if backend is None:
        from qrag.models import LocalModels

        backend = LocalModels(config)
    identity = {
        "config": config.as_dict(),
        "dataset_sha256": file_hash(dataset_path),
        "question_ids": [query.id for query, _ in examples],
        "source_sha256": source_hash(),
        "environment": environment(),
        "backend": backend.describe(),
        "methods": METHODS,
        "context_order": "original_candidate_order",
        "budget_mode": "exact_count",
        "cache_policy": "shared_features_per_question_only; no_persistent_embedding_cache",
    }
    store = RunStore(output, identity, resume)
    expected_keys = {(query.id, method) for query, _ in examples for method in METHODS}
    if not set(store.records) <= expected_keys:
        raise ValueError("Stored records contain unexpected questions or methods")
    if set(store.records) == expected_keys:
        result = summarize(list(store.records.values()))
        write_json(output / "summary.json", result)
        return result
    invocation = {"started_at": utc_now()}
    start = perf_counter()
    store.manifest["invocations"].append(invocation)
    store.manifest["status"] = "running"
    store.save_manifest()
    try:
        invocation["preparation"] = backend.prepare()
        store.save_manifest()
        for query, labels in examples:
            pending = [
                method for method in METHODS if (query.id, method) not in store.records
            ]
            if not pending:
                continue
            feature_error = None
            features = {}
            effective_k = min(config.k, len(query.documents))
            try:
                if (
                    config.k > len(query.documents)
                    and config.short_pool_policy == "error"
                ):
                    raise ValueError("Candidate pool is smaller than requested k")
                relevance, similarities, features = backend.score(query)
                problem = build_problem(
                    relevance, similarities, effective_k, config.alpha, config.beta
                )
            except Exception as exc:
                feature_error = exc
            for method in pending:
                record = {
                    "question_id": query.id,
                    "method": method,
                    "requested_k": config.k,
                    "effective_k": effective_k,
                    "candidate_ids": [doc.id for doc in query.documents],
                    "features": features,
                }
                try:
                    if feature_error is not None:
                        raise feature_error
                    selection = (
                        select_top_k(problem, relevance)
                        if method == "top_k"
                        else select_milp(problem, config.solver_time_limit)
                    )
                    record["selection"] = asdict(selection)
                    if selection.indices is None:
                        raise RuntimeError(f"No feasible incumbent: {selection.status}")
                    problem.validate_selection(selection.indices)
                    selected = tuple(query.documents[i] for i in selection.indices)
                    record.update(
                        {
                            "selected_ids": [doc.id for doc in selected],
                            "selected_titles": [doc.title for doc in selected],
                            "selected_count": len(selected),
                            "feasible": True,
                            "relevance_scores": relevance.tolist(),
                            "linear_coefficients": problem.linear.tolist(),
                            "pair_coefficients": problem.pairs.tolist(),
                        }
                    )
                    # No labels enter either score(), selection, or generate().
                    generation = backend.generate(query, selected)
                    record.update(generation)
                    record["metrics"] = {
                        **answer_metrics(generation["answer"], labels.answer),
                        **evidence_metrics(selected, labels),
                    }
                    record["status"] = "success"
                except Exception as exc:
                    record.update(
                        {
                            "status": "error",
                            "error_type": type(exc).__name__,
                            "error": str(exc),
                        }
                    )
                store.save_record(record)
                print(f"{query.id} {method}: {record['status']}", flush=True)
        result = summarize(list(store.records.values()))
        write_json(output / "summary.json", result)
        store.manifest["status"] = (
            "completed_with_errors"
            if any(row["status"] != "success" for row in store.records.values())
            else "completed"
        )
        return result
    except BaseException:
        store.manifest["status"] = "interrupted_or_failed"
        write_json(output / "failure.json", {"traceback": traceback.format_exc()})
        raise
    finally:
        invocation.update(
            {"ended_at": utc_now(), "wall_seconds": perf_counter() - start}
        )
        store.save_manifest()


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--resume", action="store_true")
    args = parser.parse_args()
    try:
        summary = run_experiment(
            load_config(args.config), args.output, resume=args.resume
        )
    except Exception as exc:
        parser.exit(1, f"Experiment failed: {exc}\n")
    print(json.dumps(summary, indent=2))
    if any(value["failed"] for value in summary["methods"].values()):
        parser.exit(
            1, "Run completed with recorded errors; inspect predictions.jsonl.\n"
        )


if __name__ == "__main__":
    main()

experiments/study.py:
"""Configuration-driven study on shared, token-safe candidate representations."""

import argparse
import json
import traceback
from dataclasses import asdict, replace
from pathlib import Path
from time import perf_counter

import numpy as np

from qrag.config import ExperimentConfig
from qrag.data import load_examples
from qrag.datasets import score_answer, score_evidence
from qrag.evidence import cached_evidence, interaction_problem
from qrag.experiments.artifacts import (
    environment,
    file_hash,
    source_hash,
    utc_now,
    write_json,
)
from qrag.experiments.journal import JournalRunStore
from qrag.models import LocalModels
from qrag.optimization import (
    select_annealing,
    select_greedy,
    select_milp,
    select_random_samples,
    select_top_k,
)
from qrag.retrieval import (
    ChunkEncoder,
    ChunkReranker,
    bm25_scores,
    reciprocal_rank_fusion,
)


def summarize(records):
    result = {"methods": {}}
    for method in sorted({r["method"] for r in records}):
        rows = [r for r in records if r["method"] == method]
        good = [r for r in rows if r["status"] == "success"]
        metrics = {
            key: sum(r.get("metrics", {}).get(key, 0.0) for r in rows) / len(rows)
            for key in ("answer_f1", "answer_em")
        }
        means = {}
        for key in ("document_recall", "all_supporting_documents"):
            values = [r["metrics"][key] for r in good if r["metrics"][key] is not None]
            means[key + "_successful_only"] = float(np.mean(values)) if values else None
        for key in (
            "context_tokens",
            "input_tokens",
            "selected_count",
            "selection_seconds",
            "generation_seconds",
        ):
            means[key + "_successful_only"] = (
                float(np.mean([r[key] for r in good])) if good else None
            )
        result["methods"][method] = {
            "questions": len(rows),
            "failures": len(rows) - len(good),
            **metrics,
            **means,
        }
    return result


def validate_spec(spec):
    allowed = {
        "model",
        "methods",
        "budget_mode",
        "context_budget",
        "candidate_limit",
        "reranker",
        "scope",
        "cache",
        "seed",
        "limit",
        "dataset_sha256",
    }
    if set(spec) - allowed:
        raise ValueError(f"Unknown study settings: {set(spec) - allowed}")
    config = ExperimentConfig(**spec["model"])
    methods = spec["methods"]
    if not methods or len({m["name"] for m in methods}) != len(methods):
        raise ValueError("Method names must be nonempty and unique")
    for m in methods:
        if m["solver"] not in {
            "top_k",
            "bm25",
            "hybrid",
            "reranker",
            "mmr",
            "coverage",
            "greedy",
            "annealing",
            "milp",
            "qaoa",
            "random",
        }:
            raise ValueError("Unknown solver")
    if spec.get("budget_mode", "count") not in {"count", "tokens"}:
        raise ValueError("Unknown budget mode")
    if spec.get("budget_mode") == "tokens" and (
        type(spec.get("context_budget")) is not int or spec["context_budget"] < 1
    ):
        raise ValueError("Need positive context token budget")
    if (
        type(spec.get("candidate_limit", 100)) is not int
        or spec.get("candidate_limit", 100) < 1
    ):
        raise ValueError("Invalid candidate limit")
    return config


def choose(problem, method, relevance, similarities, coverage, lexical, rerank):
    solver = method["solver"]
    if solver in {"top_k", "bm25", "hybrid", "reranker"}:
        scores = {
            "top_k": relevance,
            "bm25": lexical,
            "hybrid": reciprocal_rank_fusion(relevance, lexical),
            "reranker": rerank,
        }[solver]
        if scores is None:
            raise ValueError("Reranker not configured")
        return select_top_k(problem, scores), {}
    if solver in {"mmr", "coverage", "greedy"}:
        return select_greedy(
            problem,
            relevance,
            similarities,
            coverage,
            {"greedy": "energy"}.get(solver, solver),
        ), {}
    if solver == "annealing":
        return select_annealing(
            problem, method.get("seed", 42), method.get("steps", 2000)
        ), {}
    if solver == "milp":
        return select_milp(problem, method.get("time_limit", 10)), {}
    if solver == "random":
        return select_random_samples(
            problem, method.get("seed", 42), method.get("shots", 1024)
        )
    from qrag.quantum import solve_qaoa

    return solve_qaoa(
        problem,
        **{
            k: v
            for k, v in method.items()
            if k
            in {"p", "seed", "shots", "max_evals", "mixer", "noise", "training_shots"}
        },
    )


def run_study(spec, output: Path, resume=False, backend=None):
    config = validate_spec(spec)
    path = Path(config.dataset)
    if spec.get("dataset_sha256") and file_hash(path) != spec["dataset_sha256"]:
        raise ValueError("Dataset hash mismatch")
    examples = load_examples(path)[: config.limit]
    model = backend if backend is not None else LocalModels(config)
    identity = {
        "spec": spec,
        "data_sha256": file_hash(path),
        "source_sha256": source_hash(),
        "question_ids": [q.id for q, _ in examples],
        "environment": environment(),
        "backend": {
            "device": model.device,
            "dtype": config.generator_dtype,
            "embedding_model": config.embedding_model,
            "embedding_revision": config.embedding_revision,
            "generator_model": config.generator_model,
            "generator_revision": config.generator_revision,
        },
    }
    store = JournalRunStore(output, identity, resume)
    expected = {(q.id, m["name"]) for q, _ in examples for m in spec["methods"]}
    if not set(store.records) <= expected:
        raise ValueError("Unexpected records")
    if set(store.records) == expected and all(
        r["status"] == "success" for r in store.records.values()
    ):
        result = summarize(list(store.records.values()))
        write_json(output / "summary.json", result)
        return result
    # Retain exact source bytes even when implementation changes in later phases.
    root = Path(__file__).resolve().parents[1]
    if not (output / "source_snapshot.json").exists():
        write_json(
            output / "source_snapshot.json",
            {
                str(p.relative_to(root)): p.read_text()
                for p in sorted(root.rglob("*.py"))
            },
        )
    invocation = {"started_at": utc_now()}
    start = perf_counter()
    store.manifest["invocations"].append(invocation)
    store.manifest["status"] = "running"
    store.save_manifest()
    encoder = None
    try:
        invocation["preparation"] = model.prepare()
        encoder = ChunkEncoder(
            model.embedder,
            Path(spec.get("cache", ".cache/study_embeddings.sqlite")),
            config.embedding_model,
            config.embedding_revision,
        )
        reranker = None
        if any(m["solver"] == "reranker" for m in spec["methods"]):
            r = spec["reranker"]
            reranker = ChunkReranker(r["model"], r["revision"], encoder, model.device)
        store.save_manifest()
        for query, labels in examples:
            pending = [
                m
                for m in spec["methods"]
                if (query.id, m["name"]) not in store.records
                or store.records[(query.id, m["name"])]["status"] != "success"
            ]
            if not pending:
                continue
            shared_error = None
            try:
                if (
                    len(query.documents) < config.k
                    and config.short_pool_policy == "error"
                    and spec.get("budget_mode", "count") == "count"
                ):
                    raise ValueError("Candidate pool smaller than requested k")
                relevance, similarities, features = encoder.score(query)
                candidate_limit = spec.get("candidate_limit", 100)
                if len(query.documents) > candidate_limit:
                    order = sorted(
                        int(i)
                        for i in np.argsort(-relevance, kind="stable")[:candidate_limit]
                    )
                    query = replace(
                        query, documents=tuple(query.documents[i] for i in order)
                    )
                    relevance = relevance[order]
                    similarities = similarities[np.ix_(order, order)]
                comp, coverage, graph = cached_evidence(
                    query, relevance, Path(".cache/study_graphs.sqlite")
                )
                feature_started = perf_counter()
                lexical = bm25_scores(query.question, query.documents)
                features["lexical_seconds"] = perf_counter() - feature_started
                feature_started = perf_counter()
                rerank = reranker.score(query) if reranker else None
                features["rerank_seconds"] = (
                    perf_counter() - feature_started if reranker else None
                )
                features["graph_lookup_seconds"] = graph["lookup_seconds"]
                mode = spec.get("budget_mode", "count")
                budgets = {}
                if mode == "tokens":
                    # Conservative additive accounting, then exact formatted verification.
                    costs = np.array(
                        [
                            len(
                                model.tokenizer.encode(
                                    f"[Source {d.id}: {d.title}]\n{d.text}",
                                    add_special_tokens=False,
                                )
                            )
                            + 10
                            for d in query.documents
                        ]
                    )
                    budgets = {
                        "token_costs": costs,
                        "token_budget": spec["context_budget"],
                        "min_count": 1,
                    }
                k = min(config.k, len(query.documents)) if mode == "count" else None
            except Exception as exc:
                shared_error = exc
            generations = {}
            for method in pending:
                row = {
                    "question_id": query.id,
                    "method": method["name"],
                    "status": "error",
                    "candidate_ids": [d.id for d in query.documents],
                }
                row["candidate_metrics"] = score_evidence(query.documents, labels)
                try:
                    if shared_error:
                        raise shared_error
                    full = interaction_problem(
                        relevance,
                        similarities,
                        k,
                        method.get("gamma", 0),
                        comp,
                        config.alpha,
                        config.beta,
                        **budgets,
                    )
                    problem = full
                    sparse_meta = {}
                    if method.get("sparsifier"):
                        from qrag.sparsification import sparsify

                        problem, sparse_meta = sparsify(
                            full,
                            comp,
                            method["sparsifier"],
                            method.get("edge_fraction", 0.5),
                            method.get("seed", 42),
                        )
                    selection, resources = choose(
                        problem,
                        method,
                        relevance,
                        similarities,
                        coverage,
                        lexical,
                        rerank,
                    )
                    row.update(
                        {
                            "selection": asdict(selection),
                            "resources": resources,
                            "sparsification": sparse_meta,
                            "linear_coefficients": full.linear.tolist(),
                            "pair_coefficients": full.pairs.tolist(),
                            "surrogate_pairs": problem.pairs.tolist(),
                            "features": features,
                            "graph": graph,
                        }
                    )
                    if selection.indices is None:
                        raise RuntimeError(
                            "Solver returned no feasible solution: " + selection.status
                        )
                    full.validate_selection(selection.indices)
                    selected = tuple(query.documents[i] for i in selection.indices)
                    reused = selection.indices in generations
                    generation = generations.get(selection.indices)
                    if generation is None:
                        generation = model.generate(query, selected)
                        generations[selection.indices] = generation
                    if (
                        mode == "tokens"
                        and generation["context_tokens"] > spec["context_budget"]
                    ):
                        raise ValueError(
                            "Actual assembled context exceeds token budget; no silent repair"
                        )
                    row.update(generation)
                    row.update(
                        {
                            "generation_reused": reused,
                            "actual_generation_seconds": 0.0
                            if reused
                            else generation["generation_seconds"],
                            "selected_ids": [d.id for d in selected],
                            "selected_titles": [d.title for d in selected],
                            "selected_count": len(selected),
                            "selection_seconds": selection.seconds,
                            "full_energy": full.energy(selection.indices),
                            "surrogate_energy": problem.energy(selection.indices),
                            "feasible": True,
                            "budget_mode": mode,
                            "estimated_token_cost": float(
                                sum(costs[list(selection.indices)])
                            )
                            if mode == "tokens"
                            else None,
                            "metrics": {
                                **score_answer(generation["answer"], labels),
                                **score_evidence(selected, labels),
                            },
                            "status": "success",
                        }
                    )
                except Exception as exc:
                    row.update({"error_type": type(exc).__name__, "error": str(exc)})
                store.save_record(row)
                print(query.id, method["name"], row["status"], flush=True)
        result = summarize(list(store.records.values()))
        write_json(output / "summary.json", result)
        store.manifest["status"] = (
            "completed_with_errors"
            if any(r["status"] != "success" for r in store.records.values())
            else "completed"
        )
        return result
    except BaseException:
        store.manifest["status"] = "interrupted_or_failed"
        write_json(output / "failure.json", {"traceback": traceback.format_exc()})
        raise
    finally:
        invocation.update(
            {"ended_at": utc_now(), "wall_seconds": perf_counter() - start}
        )
        store.save_manifest()
        if encoder:
            encoder.cache.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--resume", action="store_true")
    args = parser.parse_args()
    result = run_study(json.loads(args.config.read_text()), args.output, args.resume)
    print(json.dumps(result, indent=2))
    if any(m["failures"] for m in result["methods"].values()):
        raise SystemExit(1)


if __name__ == "__main__":
    main()

metrics.py:
"""HotpotQA-compatible answer metrics and explicitly document-level evidence metrics.

Reference semantics: https://github.com/hotpotqa/hotpot/blob/master/hotpot_evaluate_v1.py
No supporting-sentence prediction is claimed by this first implementation.
"""

import re
import string
from collections import Counter

from qrag.data import Document, EvaluationLabels


def normalize_answer(text: str) -> str:
    text = text.lower().translate(str.maketrans("", "", string.punctuation))
    return " ".join(re.sub(r"\b(a|an|the)\b", " ", text).split())


def answer_metrics(prediction: str, reference: str) -> dict[str, float]:
    pred, gold = normalize_answer(prediction), normalize_answer(reference)
    exact = float(pred == gold)
    specials = {"yes", "no", "noanswer"}
    precision = recall = f1 = 0.0
    if not ((pred in specials or gold in specials) and pred != gold):
        pred_tokens, gold_tokens = pred.split(), gold.split()
        overlap = sum((Counter(pred_tokens) & Counter(gold_tokens)).values())
        if overlap:
            precision = overlap / len(pred_tokens)
            recall = overlap / len(gold_tokens)
            f1 = 2 * precision * recall / (precision + recall)
    return {
        "answer_em": exact,
        "answer_f1": f1,
        "answer_precision": precision,
        "answer_recall": recall,
    }


def evidence_metrics(
    selected: tuple[Document, ...], labels: EvaluationLabels
) -> dict[str, float | None]:
    predicted = {doc.title for doc in selected}
    gold = labels.supporting_titles
    if not gold:
        return {
            "document_precision": None,
            "document_recall": None,
            "all_supporting_documents": None,
        }
    correct = len(predicted & gold)
    return {
        "document_precision": correct / len(predicted) if predicted else 0.0,
        "document_recall": correct / len(gold),
        "all_supporting_documents": float(gold <= predicted),
    }

optimization.py:
"""One energy definition shared by ranking, MILP and a tiny exhaustive oracle."""

from dataclasses import dataclass
from itertools import combinations
from time import perf_counter

import numpy as np
from scipy.optimize import Bounds, LinearConstraint, milp
from scipy.sparse import coo_array


@dataclass(frozen=True)
class SelectionProblem:
    linear: np.ndarray
    pairs: np.ndarray  # Strict upper triangle: each interaction is counted once.
    k: int | None
    token_costs: np.ndarray | None = None
    token_budget: int | None = None
    min_count: int = 0

    def __post_init__(self) -> None:
        linear = np.array(self.linear, dtype=float, copy=True)
        pairs = np.array(self.pairs, dtype=float, copy=True)
        if linear.ndim != 1 or not len(linear):
            raise ValueError("linear must be a nonempty vector")
        if pairs.shape != (len(linear), len(linear)):
            raise ValueError("pair matrix shape does not match linear vector")
        if not np.isfinite(linear).all() or not np.isfinite(pairs).all():
            raise ValueError("Objective coefficients must be finite")
        if np.any(np.tril(pairs) != 0):
            raise ValueError("pairs must have a zero diagonal and lower triangle")
        if self.k is not None and (
            type(self.k) is not int or not 0 <= self.k <= len(linear)
        ):
            raise ValueError("k must be an integer between zero and candidate count")
        if type(self.min_count) is not int or not 0 <= self.min_count <= len(linear):
            raise ValueError("Invalid minimum count")
        if self.k is not None and self.min_count > self.k:
            raise ValueError("Minimum count exceeds k")
        if self.token_costs is not None:
            costs = np.array(self.token_costs, dtype=float, copy=True)
            if (
                costs.shape != linear.shape
                or not np.isfinite(costs).all()
                or np.any(costs <= 0)
            ):
                raise ValueError("Token costs must be positive finite candidate costs")
            if type(self.token_budget) is not int or self.token_budget < 0:
                raise ValueError("Token budget must be a nonnegative integer")
            costs.flags.writeable = False
            object.__setattr__(self, "token_costs", costs)
        elif self.token_budget is not None or self.k is None:
            raise ValueError("A variable-count problem requires token costs and budget")
        linear.flags.writeable = pairs.flags.writeable = False
        object.__setattr__(self, "linear", linear)
        object.__setattr__(self, "pairs", pairs)

    def validate_selection(self, indices: tuple[int, ...]) -> None:
        if (self.k is not None and len(indices) != self.k) or len(set(indices)) != len(
            indices
        ):
            raise ValueError("Selection must contain exactly k distinct indices")
        if any(type(i) is not int or not 0 <= i < len(self.linear) for i in indices):
            raise ValueError("Invalid candidate index")
        if len(indices) < self.min_count:
            raise ValueError("Selection violates minimum count")
        if (
            self.token_costs is not None
            and sum(self.token_costs[list(indices)]) > self.token_budget + 1e-8
        ):
            raise ValueError("Selection exceeds token budget")

    def energy(self, indices: tuple[int, ...]) -> float:
        self.validate_selection(indices)
        x = np.zeros(len(self.linear))
        x[list(indices)] = 1
        return float(self.linear @ x + x @ self.pairs @ x)


def build_problem(
    relevance: np.ndarray,
    similarities: np.ndarray,
    k: int,
    alpha: float = 1.0,
    beta: float = 0.2,
) -> SelectionProblem:
    """Match the legacy positive-similarity redundancy objective, adding exact k."""
    if not np.isfinite([alpha, beta]).all() or alpha < 0 or beta < 0:
        raise ValueError("alpha and beta must be finite and nonnegative")
    return SelectionProblem(
        -alpha * np.asarray(relevance),
        np.triu(beta * np.maximum(np.asarray(similarities), 0), k=1),
        k,
    )


@dataclass(frozen=True)
class SelectionResult:
    indices: tuple[int, ...] | None
    energy: float | None
    status: str
    optimal: bool
    seconds: float
    lower_bound: float | None = None
    relative_gap: float | None = None
    message: str = ""


def select_top_k(problem: SelectionProblem, relevance: np.ndarray) -> SelectionResult:
    start = perf_counter()
    scores = np.asarray(relevance, dtype=float)
    if scores.shape != problem.linear.shape or not np.isfinite(scores).all():
        raise ValueError("Invalid relevance vector")
    ranked = []
    for i in np.argsort(-scores, kind="stable"):
        if problem.k is not None and len(ranked) >= problem.k:
            break
        if (
            problem.token_costs is None
            or sum(problem.token_costs[ranked]) + problem.token_costs[i]
            <= problem.token_budget
        ):
            ranked.append(int(i))
    indices = tuple(sorted(int(i) for i in ranked))
    return SelectionResult(
        indices, problem.energy(indices), "ranking", False, perf_counter() - start
    )


def _finite_or_none(value: object) -> float | None:
    return float(value) if value is not None and np.isfinite(value) else None


def select_milp(problem: SelectionProblem, time_limit: float = 10.0) -> SelectionResult:
    """Linearize x_i*x_j exactly; y is continuous because x is binary."""
    if not np.isfinite(time_limit) or time_limit <= 0:
        raise ValueError("time_limit must be positive and finite")
    start = perf_counter()
    n = len(problem.linear)
    edges = [(int(i), int(j)) for i, j in zip(*np.nonzero(problem.pairs))]
    coefficients = np.r_[problem.linear, [problem.pairs[i, j] for i, j in edges]]
    row_ids, col_ids, values = [], [], []
    lower, upper = [], []

    def add_row(entries: dict[int, float], low: float, high: float) -> None:
        row = len(lower)
        for col, value in entries.items():
            row_ids.append(row)
            col_ids.append(col)
            values.append(value)
        lower.append(low)
        upper.append(high)

    add_row(
        dict.fromkeys(range(n), 1.0),
        problem.k if problem.k is not None else problem.min_count,
        problem.k if problem.k is not None else np.inf,
    )
    if problem.token_costs is not None:
        add_row(dict(enumerate(problem.token_costs)), -np.inf, problem.token_budget)
    for offset, (i, j) in enumerate(edges):
        y = n + offset
        add_row({y: 1, i: -1}, -np.inf, 0)
        add_row({y: 1, j: -1}, -np.inf, 0)
        add_row({y: 1, i: -1, j: -1}, -1, np.inf)
    matrix = coo_array(
        (np.asarray(values, dtype=float), (row_ids, col_ids)),
        shape=(len(lower), len(coefficients)),
    ).tocsc()
    result = milp(
        coefficients,
        integrality=np.r_[np.ones(n), np.zeros(len(edges))],
        bounds=Bounds(0, 1),
        constraints=LinearConstraint(matrix, lower, upper),
        options={"time_limit": time_limit, "mip_rel_gap": 0.0},
    )
    status = {0: "optimal", 1: "limit", 2: "infeasible", 3: "unbounded", 4: "error"}
    indices = None
    if result.x is not None:
        x = np.asarray(result.x[:n])
        if not np.isfinite(x).all() or np.max(np.abs(x - np.rint(x))) > 1e-5:
            raise RuntimeError("MILP returned a nonintegral incumbent")
        indices = tuple(int(i) for i in np.flatnonzero(np.rint(x)))
        problem.validate_selection(indices)
    if result.status == 0 and indices is None:
        raise RuntimeError("MILP reported optimality without an incumbent")
    return SelectionResult(
        indices,
        problem.energy(indices) if indices is not None else None,
        status.get(result.status, "error"),
        result.status == 0,
        perf_counter() - start,
        _finite_or_none(getattr(result, "mip_dual_bound", None)),
        _finite_or_none(getattr(result, "mip_gap", None)),
        str(result.message),
    )


def select_exhaustive(problem: SelectionProblem) -> SelectionResult:
    """Correctness reference only, deliberately limited to small candidate pools."""
    if len(problem.linear) > 20:
        raise ValueError("Exhaustive oracle is restricted to at most 20 candidates")
    start = perf_counter()
    sizes = (
        [problem.k]
        if problem.k is not None
        else range(problem.min_count, len(problem.linear) + 1)
    )

    def feasible():
        for size in sizes:
            for candidate in combinations(range(len(problem.linear)), size):
                try:
                    problem.validate_selection(candidate)
                except ValueError:
                    continue
                yield candidate

    indices = min(feasible(), key=problem.energy, default=None)
    if indices is None:
        return SelectionResult(None, None, "infeasible", False, perf_counter() - start)
    energy = problem.energy(indices)
    return SelectionResult(
        indices, energy, "optimal", True, perf_counter() - start, energy, 0.0
    )


def raw_energy(problem: SelectionProblem, indices) -> float:
    x = np.zeros(len(problem.linear))
    x[list(indices)] = 1
    return float(problem.linear @ x + x @ problem.pairs @ x)


def select_greedy(
    problem, relevance=None, similarities=None, coverage=None, mode="energy"
):
    start = perf_counter()
    selected = []
    candidates = set(range(len(problem.linear)))
    while candidates and (problem.k is None or len(selected) < problem.k):
        feasible = [
            i
            for i in sorted(candidates)
            if problem.token_costs is None
            or sum(problem.token_costs[selected]) + problem.token_costs[i]
            <= problem.token_budget
        ]
        if not feasible:
            break

        def gain(i):
            if mode == "mmr":
                redundancy = max((similarities[i, j] for j in selected), default=0)
                return 0.7 * relevance[i] - 0.3 * redundancy
            if mode == "coverage":
                before = (
                    np.max(coverage[selected], axis=0)
                    if selected
                    else np.zeros(coverage.shape[1])
                )
                return (
                    float(np.maximum(before, coverage[i]).sum() - before.sum())
                    + 0.1 * relevance[i]
                )
            return raw_energy(problem, selected) - raw_energy(problem, selected + [i])

        best = max(feasible, key=lambda i: (gain(i), -i))
        if problem.k is None and len(selected) >= problem.min_count and gain(best) <= 0:
            break
        selected.append(best)
        candidates.remove(best)
    indices = tuple(sorted(selected))
    problem.validate_selection(indices)
    return SelectionResult(
        indices, problem.energy(indices), "heuristic", False, perf_counter() - start
    )


def select_annealing(problem, seed=42, steps=2000):
    """Feasible fixed-count swaps or token-budget add/drop/swap moves."""
    start = perf_counter()
    rng = np.random.default_rng(seed)
    initial = select_top_k(problem, -problem.linear).indices
    current, best = set(initial), tuple(initial)
    current_energy = best_energy = problem.energy(best)
    scale = max(1e-3, np.abs(problem.linear).sum() + np.abs(problem.pairs).sum())
    for step in range(steps):
        candidate = set(current)
        selected = sorted(candidate)
        other = sorted(set(range(len(problem.linear))) - candidate)
        if problem.k is not None or rng.random() < 0.5:
            if not selected or not other:
                continue
            candidate.remove(int(rng.choice(selected)))
            candidate.add(int(rng.choice(other)))
        elif rng.random() < 0.5 and other:
            candidate.add(int(rng.choice(other)))
        elif selected:
            candidate.remove(int(rng.choice(selected)))
        indices = tuple(sorted(candidate))
        try:
            problem.validate_selection(indices)
        except ValueError:
            continue
        energy = problem.energy(indices)
        temperature = scale * 0.1 * (1e-4 ** (step / max(1, steps - 1)))
        if energy < current_energy or rng.random() < np.exp(
            min(0, (current_energy - energy) / temperature)
        ):
            current, current_energy = candidate, energy
        if energy < best_energy:
            best, best_energy = indices, energy
    return SelectionResult(
        best, best_energy, "annealing", False, perf_counter() - start
    )


def select_random_samples(problem, seed=42, shots=1024):
    """Strong small-instance control: best of the same number of feasible samples."""
    if problem.k is None or problem.token_costs is not None or shots < 1:
        raise ValueError(
            "Uniform feasible sampling requires a fixed count and positive shots"
        )
    start = perf_counter()
    rng = np.random.default_rng(seed)
    candidates = {
        tuple(
            sorted(
                int(i)
                for i in rng.choice(len(problem.linear), problem.k, replace=False)
            )
        )
        for _ in range(shots)
    }
    best = min(candidates, key=lambda indices: (problem.energy(indices), indices))
    return SelectionResult(
        best,
        problem.energy(best),
        "random_best_of_samples",
        False,
        perf_counter() - start,
    ), {
        "classical_baseline": "uniform feasible fixed-count sampling",
        "seed": seed,
        "shots": shots,
        "unique_subsets": len(candidates),
        "selection_policy": "minimum common objective over all sampled feasible subsets",
    }

retrieval.py:
"""Token-safe chunks, content-addressed embeddings, and a checked exact FAISS index.

Optional model/search packages are imported only when their capability is used.
"""

import hashlib
import json
import re
import sqlite3
from contextlib import closing
from dataclasses import asdict, dataclass
from pathlib import Path
from threading import RLock
from time import perf_counter

import numpy as np

from qrag.data import Document, QueryInput
from qrag.experiments.artifacts import file_hash, value_hash, write_json

CHUNK_POLICY = "sentence-greedy-v1-title64-long-sentence-offset-window-overlap32"


@dataclass(frozen=True)
class Chunk:
    id: str
    source_id: str
    title: str
    text: str
    start: int
    end: int
    sentence_ids: tuple[int, ...]
    embedding_text: str

    @property
    def content_hash(self):
        return hashlib.sha256(self.embedding_text.encode()).hexdigest()


def chunk_document(
    doc: Document, tokenizer, max_tokens=240, overlap=32
) -> tuple[Chunk, ...]:
    """Preserve source character offsets, splitting a long sentence only when needed."""
    if max_tokens < 16 or not 0 <= overlap < max_tokens // 2:
        raise ValueError("Invalid chunk size/overlap")
    title_ids = tokenizer(doc.title, add_special_tokens=False)["input_ids"]
    title = tokenizer.decode(title_ids[:64], skip_special_tokens=True)
    prefix = title + "\n"

    def count(text):
        return len(tokenizer(prefix + text, add_special_tokens=True)["input_ids"])

    if count("") >= max_tokens - 4:
        raise ValueError("Title consumes chunk token budget")
    spans = []
    offset = 0
    if doc.sentences:
        for i, sentence in enumerate(doc.sentences):
            spans.append((offset, offset + len(sentence), i))
            offset += len(sentence) + 1
    else:
        boundaries = [
            0,
            *[m.end() for m in re.finditer(r"[.!?](?:\s+|$)|\n+", doc.text)],
            len(doc.text),
        ]
        spans = [
            (a, b, i)
            for i, (a, b) in enumerate(zip(boundaries, boundaries[1:]))
            if doc.text[a:b].strip()
        ]
    atoms = []
    for start, end, sid in spans:
        if not doc.text[start:end].strip():
            continue
        if count(doc.text[start:end]) <= max_tokens:
            atoms.append((start, end, sid))
            continue
        offsets = tokenizer(
            doc.text[start:end], add_special_tokens=False, return_offsets_mapping=True
        )["offset_mapping"]
        pos = 0
        while pos < len(offsets):
            stop = min(len(offsets), pos + max_tokens - count("") - 2)
            while (
                stop > pos
                and count(
                    doc.text[start + offsets[pos][0] : start + offsets[stop - 1][1]]
                )
                > max_tokens
            ):
                stop -= 1
            if stop == pos:
                raise ValueError("Cannot represent one token within chunk budget")
            atoms.append((start + offsets[pos][0], start + offsets[stop - 1][1], sid))
            if stop == len(offsets):
                break
            pos = max(pos + 1, stop - overlap)
    chunks = []
    i = 0
    while i < len(atoms):
        start, end, _ = atoms[i]
        ids = {atoms[i][2]}
        j = i + 1
        while j < len(atoms) and count(doc.text[start : atoms[j][1]]) <= max_tokens:
            end = atoms[j][1]
            ids.add(atoms[j][2])
            j += 1
        text = doc.text[start:end]
        chunks.append(
            Chunk(
                f"{doc.id}:c{len(chunks)}",
                doc.id,
                doc.title,
                text,
                start,
                end,
                tuple(sorted(ids)),
                prefix + text,
            )
        )
        i = j
    if not chunks:
        raise ValueError("Document has no encodable content")
    return tuple(chunks)


class EmbeddingCache:
    def __init__(self, path: Path, namespace: dict):
        path.parent.mkdir(parents=True, exist_ok=True)
        self.connection = sqlite3.connect(path, check_same_thread=False)
        self.connection.execute("PRAGMA journal_mode=WAL")
        self.connection.execute(
            "CREATE TABLE IF NOT EXISTS embeddings (key TEXT PRIMARY KEY, dim INTEGER, digest TEXT, value BLOB)"
        )
        self.namespace = namespace
        self.hits = self.misses = 0
        self.lock = RLock()

    def key(self, text, kind):
        return value_hash({"namespace": self.namespace, "text": text, "kind": kind})

    def get(self, text: str, kind="document"):
        with self.lock:
            row = self.connection.execute(
                "SELECT dim,digest,value FROM embeddings WHERE key=?",
                (self.key(text, kind),),
            ).fetchone()
            if row is None:
                self.misses += 1
                return None
            dim, digest, data = row
            vector = np.frombuffer(data, dtype="<f4").copy()
            if (
                hashlib.sha256(data).hexdigest() != digest
                or vector.shape != (dim,)
                or not np.isfinite(vector).all()
            ):
                raise ValueError("Corrupt embedding cache entry")
            self.hits += 1
            return vector

    def put(self, text, vector, kind="document"):
        vector = np.asarray(vector, dtype="<f4")
        if vector.ndim != 1 or not len(vector) or not np.isfinite(vector).all():
            raise ValueError("Invalid embedding vector")
        data = vector.tobytes()
        with self.lock, self.connection:
            self.connection.execute(
                "INSERT OR REPLACE INTO embeddings VALUES (?,?,?,?)",
                (
                    self.key(text, kind),
                    len(vector),
                    hashlib.sha256(data).hexdigest(),
                    data,
                ),
            )

    def close(self):
        self.connection.close()


class ChunkEncoder:
    def __init__(
        self, embedder, cache_path: Path, model_id: str, revision: str, max_tokens=240
    ):
        self.model = embedder
        self.tokenizer = embedder.tokenizer
        self.max_tokens = min(max_tokens, embedder.max_seq_length)
        self.identity = {
            "model": model_id,
            "revision": revision,
            "policy": CHUNK_POLICY,
            "max_tokens": self.max_tokens,
            "normalize": True,
            "dtype": "float32",
            "document_aggregation": "mean-chunks-then-unit-normalize",
        }
        self.cache = EmbeddingCache(cache_path, self.identity)

    def encode(self, texts, kind="document"):
        values = [self.cache.get(t, kind) for t in texts]
        missing = sorted({text for text, value in zip(texts, values) if value is None})
        if missing:
            for text in missing:
                if (
                    len(self.tokenizer(text, add_special_tokens=True)["input_ids"])
                    > self.model.max_seq_length
                ):
                    raise ValueError("Unchunked embedding input exceeds model limit")
            vectors = self.model.encode(
                missing,
                normalize_embeddings=True,
                convert_to_numpy=True,
                batch_size=64,
                show_progress_bar=False,
            )
            replacements = dict(zip(missing, vectors, strict=True))
            for text, vector in replacements.items():
                self.cache.put(text, vector, kind)
            values = [
                replacements[text] if value is None else value
                for text, value in zip(texts, values)
            ]
        array = np.asarray(values, dtype=np.float32)
        if array.ndim != 2 or not np.isfinite(array).all():
            raise ValueError("Invalid encoded batch")
        return array

    def score(self, query: QueryInput):
        start = perf_counter()
        chunks = [
            chunk_document(d, self.tokenizer, self.max_tokens) for d in query.documents
        ]
        flattened = [c for group in chunks for c in group]
        vectors = self.encode([c.embedding_text for c in flattened])
        docs, position = [], 0
        for group in chunks:
            vector = vectors[position : position + len(group)].mean(axis=0)
            norm = np.linalg.norm(vector)
            if norm <= 0:
                raise ValueError("Zero document embedding")
            docs.append(vector / norm)
            position += len(group)
        docs = np.asarray(docs, dtype=np.float32)
        question = self.encode([query.question], kind="query")[0]
        return (
            docs @ question,
            docs @ docs.T,
            {
                "shared_feature_seconds": perf_counter() - start,
                "chunk_count": len(flattened),
                "chunk_ids": [c.id for c in flattened],
                "cache_hits_total": self.cache.hits,
                "cache_misses_total": self.cache.misses,
                "policy": self.identity,
                "truncated_embedding_positions": [],
            },
        )


def bm25_scores(question: str, documents) -> np.ndarray:
    from rank_bm25 import BM25Okapi

    def tokenize(text):
        return re.findall(r"\w+", text.casefold())

    return np.asarray(
        BM25Okapi([tokenize(d.title + " " + d.text) for d in documents]).get_scores(
            tokenize(question)
        )
    )


def reciprocal_rank_fusion(*scores, constant=60):
    if not scores or constant <= 0:
        raise ValueError("Need score vectors and positive rank constant")
    n = len(scores[0])
    result = np.zeros(n)
    for vector in scores:
        if np.shape(vector) != (n,) or not np.isfinite(vector).all():
            raise ValueError("Invalid rank vector")
        order = np.argsort(-np.asarray(vector), kind="stable")
        result[order] += 1 / (constant + np.arange(1, n + 1))
    return result


class ExactIndex:
    """Immutable FAISS/SQLite bundle, checked against content hashes on load."""

    def __init__(self, directory: Path, expected_identity: dict | None = None):
        import faiss

        metadata = json.loads((directory / "manifest.json").read_text())
        if expected_identity is not None and metadata["identity"] != expected_identity:
            raise ValueError("Index representation identity mismatch")
        for name, digest in metadata["files"].items():
            if file_hash(directory / name) != digest:
                raise ValueError("Index bundle checksum mismatch")
        self.index = faiss.read_index(str(directory / "vectors.faiss"))
        with closing(sqlite3.connect(directory / "metadata.sqlite")) as db:
            self.rows = [
                json.loads(r[0])
                for r in db.execute("SELECT payload FROM chunks ORDER BY position")
            ]
        if self.index.ntotal != len(self.rows):
            raise ValueError("Index and metadata length mismatch")
        self.manifest = metadata

    @classmethod
    def build(cls, directory, chunks, vectors, identity):
        import faiss

        vectors = np.ascontiguousarray(vectors, dtype=np.float32)
        if (
            vectors.ndim != 2
            or len(vectors) != len(chunks)
            or not len(vectors)
            or not np.isfinite(vectors).all()
        ):
            raise ValueError("Invalid index embeddings")
        if len({c.id for c in chunks}) != len(chunks):
            raise ValueError("Duplicate chunk IDs")
        if not np.allclose(np.linalg.norm(vectors, axis=1), 1, atol=1e-3):
            raise ValueError("Cosine index requires unit embeddings")
        directory.mkdir(parents=True, exist_ok=False)
        index = faiss.IndexFlatIP(vectors.shape[1])
        index.add(vectors)
        faiss.write_index(index, str(directory / "vectors.faiss"))
        with closing(sqlite3.connect(directory / "metadata.sqlite")) as db, db:
            db.execute(
                "CREATE TABLE chunks (position INTEGER PRIMARY KEY, payload TEXT)"
            )
            db.executemany(
                "INSERT INTO chunks VALUES (?,?)",
                [(i, json.dumps(asdict(c))) for i, c in enumerate(chunks)],
            )
        write_json(
            directory / "manifest.json",
            {
                "identity": identity,
                "count": len(chunks),
                "dimension": vectors.shape[1],
                "files": {
                    name: file_hash(directory / name)
                    for name in ("vectors.faiss", "metadata.sqlite")
                },
            },
        )
        return cls(directory, identity)

    def search(self, vector, k=10):
        vector = np.asarray(vector, dtype=np.float32)
        if vector.shape != (self.index.d,) or not np.isfinite(vector).all() or k < 1:
            raise ValueError("Invalid search request")
        norm = np.linalg.norm(vector)
        if norm <= 0:
            raise ValueError("Zero query vector")
        scores, positions = self.index.search(
            np.ascontiguousarray((vector / norm)[None]), min(k, len(self.rows))
        )
        # Stable secondary ID ordering for exact ties within the retrieved set.
        return sorted(
            [(self.rows[int(i)], float(s)) for i, s in zip(positions[0], scores[0])],
            key=lambda x: (-x[1], x[0]["id"]),
        )


class ChunkReranker:
    def __init__(self, model_name, revision, encoder, device="cpu"):
        from sentence_transformers import CrossEncoder

        self.model = CrossEncoder(
            model_name, revision=revision, device=device, max_length=512
        )
        self.encoder = encoder
        self.identity = {
            "model": model_name,
            "revision": revision,
            "aggregation": "max-chunk-logit",
        }

    def score(self, query):
        pairs, groups = [], []
        for i, doc in enumerate(query.documents):
            for chunk in chunk_document(
                doc, self.encoder.tokenizer, self.encoder.max_tokens
            ):
                # Cross-encoder has its own tokenizer/limit; check paired length.
                if (
                    len(
                        self.model.tokenizer(
                            query.question, chunk.embedding_text, truncation=False
                        )["input_ids"]
                    )
                    > 512
                ):
                    raise ValueError("Reranker pair exceeds model limit")
                pairs.append((query.question, chunk.embedding_text))
                groups.append(i)
        logits = self.model.predict(pairs, batch_size=32, show_progress_bar=False)
        output = np.full(len(query.documents), -np.inf)
        for group, score in zip(groups, logits, strict=True):
            output[group] = max(output[group], float(score))
        return output

sparsification.py:
"""Matched unordered-edge budgets with an explicit full-objective error bound."""

from dataclasses import replace
from time import perf_counter

import numpy as np


def sparsify(problem, complementarity, rule="evidence", fraction=0.5, seed=42):
    started = perf_counter()
    if (
        rule not in {"evidence", "absolute", "random", "degree"}
        or not np.isfinite(fraction)
        or not 0 <= fraction <= 1
    ):
        raise ValueError("Unknown rule or invalid edge fraction")
    comp = np.asarray(complementarity)
    if (
        comp.shape != problem.pairs.shape
        or not np.isfinite(comp).all()
        or np.any(comp < 0)
    ):
        raise ValueError("Invalid evidence priorities")
    edges = [(int(i), int(j)) for i, j in zip(*np.nonzero(problem.pairs))]
    budget = int(np.floor(fraction * len(edges)))

    def magnitude(edge):
        return abs(problem.pairs[edge])

    absolute = sorted(edges, key=lambda e: (-magnitude(e), *e))
    protected = []
    if rule == "absolute":
        ordered = absolute
    elif rule == "random":
        order = np.random.default_rng(seed).permutation(len(edges))
        ordered = [edges[int(i)] for i in order]
    elif rule == "degree":
        ranks = {}
        for node in range(len(problem.linear)):
            neighbors = sorted(
                [e for e in edges if node in e], key=lambda e: (-magnitude(e), *e)
            )
            for rank, edge in enumerate(neighbors):
                ranks[edge] = min(ranks.get(edge, rank), rank)
        ordered = sorted(edges, key=lambda e: (ranks[e], -magnitude(e), *e))
    else:
        # Reserve at most half the hard budget for potential evidence bridges;
        # when protected candidates exceed this quota, rank them explicitly.
        candidates = sorted(
            [e for e in edges if comp[e] > 0],
            key=lambda e: (-comp[e] * np.sqrt(magnitude(e)), -magnitude(e), *e),
        )
        protected = candidates[: min(budget, int(np.ceil(budget / 2)))]
        ordered = protected + [e for e in absolute if e not in set(protected)]
    retained = set(ordered[:budget])
    pairs = np.zeros_like(problem.pairs)
    for edge in retained:
        pairs[edge] = problem.pairs[edge]
    delta = float(np.abs(problem.pairs - pairs).sum())
    result = replace(problem, pairs=pairs)
    return result, {
        "rule": rule,
        "edge_fraction": fraction,
        "seed": seed,
        "available_edges": len(edges),
        "retained_edges": len(retained),
        "protected_edges": len(protected),
        "retained_indices": [list(e) for e in sorted(retained)],
        "removed_l1": delta,
        "full_gap_bound_for_exact_sparse_solution": 2 * delta,
        "seconds": perf_counter() - started,
        "degree_symmetry": "minimum endpoint neighbor rank; exact unordered-edge budget",
    }
